import{_ as r,I as a,c as s,o,ah as h,J as i}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"Hexagram 2 Meaning: Kun, The Receptive","description":"Hexagram 2 meaning in the I Ching: learn how Kun, The Receptive, relates to support, steadiness, yielding strength, and timing.","frontmatter":{"title":"Hexagram 2 Meaning: Kun, The Receptive","description":"Hexagram 2 meaning in the I Ching: learn how Kun, The Receptive, relates to support, steadiness, yielding strength, and timing."},"headers":[],"relativePath":"en/articles/hexagram-2-meaning/index.md","filePath":"en/articles/hexagram-2-meaning/index.md"}'),l={name:"en/articles/hexagram-2-meaning/index.md"};function g(m,e,d,p,c,u){const n=a("SeoTopicCluster"),t=a("SeoDownloadPanel");return o(),s("div",null,[e[0]||(e[0]=h('<h1 id="hexagram-2-meaning-kun-the-receptive" tabindex="-1">Hexagram 2 Meaning: Kun, The Receptive <a class="header-anchor" href="#hexagram-2-meaning-kun-the-receptive" aria-label="Permalink to “Hexagram 2 Meaning: Kun, The Receptive”">​</a></h1><p><strong>Hexagram 2</strong>, usually called <strong>Kun</strong> or <strong>The Receptive</strong>, is often paired with Hexagram 1. If Qian represents creative initiative, Kun represents:</p><ul><li>receptivity</li><li>steadiness</li><li>support</li><li>endurance</li><li>strength through yielding</li></ul><p>This does not mean weakness. Kun is strong in a different mode.</p><h2 id="what-hexagram-2-usually-means" tabindex="-1">What Hexagram 2 usually means <a class="header-anchor" href="#what-hexagram-2-usually-means" aria-label="Permalink to “What Hexagram 2 usually means”">​</a></h2><p>Kun often appears when the right approach is:</p><ul><li>to receive rather than force</li><li>to support rather than dominate</li><li>to stabilize rather than rush</li><li>to work with conditions rather than against them</li></ul><p>It often points to deep patience and disciplined responsiveness.</p><h2 id="the-common-misunderstanding" tabindex="-1">The common misunderstanding <a class="header-anchor" href="#the-common-misunderstanding" aria-label="Permalink to “The common misunderstanding”">​</a></h2><p>Some readers think Hexagram 2 means “do nothing.” That is too simplistic.</p><p>Kun is not passive emptiness. It is:</p><ul><li>grounded responsiveness</li><li>practical follow-through</li><li>staying aligned with what the time requires</li></ul><p>Its lesson is not surrender out of helplessness. It is receptive strength.</p><h2 id="questions-to-ask-when-hexagram-2-appears" tabindex="-1">Questions to ask when Hexagram 2 appears <a class="header-anchor" href="#questions-to-ask-when-hexagram-2-appears" aria-label="Permalink to “Questions to ask when Hexagram 2 appears”">​</a></h2><ul><li>Where should I stop pushing?</li><li>What needs support rather than control?</li><li>What kind of patience is required here?</li><li>Am I resisting the shape of the situation?</li></ul><p>This hexagram is often wise when timing matters more than force.</p><h2 id="moving-lines-in-hexagram-2" tabindex="-1">Moving lines in Hexagram 2 <a class="header-anchor" href="#moving-lines-in-hexagram-2" aria-label="Permalink to “Moving lines in Hexagram 2”">​</a></h2><p>If Kun has moving lines, the reading becomes more specific. Receptivity may need to become:</p><ul><li>more disciplined</li><li>more clearly bounded</li><li>more responsive to change</li></ul><p>That is why line context matters so much in actual interpretation.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related guides”">​</a></h2><ul><li><a href="./../hexagram-1-meaning/">Hexagram 1 Meaning</a></li><li><a href="./../how-to-read-i-ching/">How to Read the I Ching</a></li><li><a href="./../i-ching-for-beginners/">I Ching for Beginners</a></li><li><a href="./../moving-lines/">Moving Lines in the I Ching</a></li></ul>',22)),i(n,{title:"Hexagram Study Cluster",intro:"Use this cluster to connect individual hexagram meaning pages back to broader I Ching structure and method.",links:[{text:"Hexagram 1 Meaning",href:"../hexagram-1-meaning/"},{text:"64 Hexagrams Guide",href:"../64-hexagrams-guide/"},{text:"Hexagram Structure",href:"../structure/"},{text:"Yin, Yang, and the Trigrams",href:"../yinyang/"},{text:"I Ching Basics",href:"../basics/"}]}),i(t,{image:"/screenshots/hexagram-globe.png","image-alt":"Hexagram reference screenshot",links:[{text:"Hexagram 1 Meaning",href:"../hexagram-1-meaning/"},{text:"How to Read the I Ching",href:"../how-to-read-i-ching/"},{text:"I Ching for Beginners",href:"../i-ching-for-beginners/"}]})])}const v=r(l,[["render",g]]);export{f as __pageData,v as default};
